package com.configmonitor.app;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.net.*;import android.os.*;import androidx.core.app.NotificationCompat;import org.json.*;import java.util.*;import java.util.concurrent.*;
public final class MonitorService extends Service {
 public static volatile boolean serviceAlive=false;public static volatile int active=0,queued=0;public static volatile Cadence schedule=new Cadence(false,true,0,0,0,0,20000);private final ScheduledExecutorService clock=Executors.newSingleThreadScheduledExecutor();private final ExecutorService workers=Executors.newCachedThreadPool();private final Set<Long> busy=ConcurrentHashMap.newKeySet();private final Map<Long,Long> due=new HashMap<>();private final Handler main=new Handler(Looper.getMainLooper());private volatile boolean destroyed=false;private long epoch=0;private long nextRound=0;private boolean offline=false,lastAlertWindow=false;private long lastAlertSince=-1;private PowerManager.WakeLock wake;private ConnectivityManager cm;private ConnectivityManager.NetworkCallback callback;
 public static void command(Context c,String action,long id){Intent i=new Intent(c,MonitorService.class).setAction(action).putExtra("id",id);if(Build.VERSION.SDK_INT>=26)c.startForegroundService(i);else c.startService(i);}
 @Override public void onCreate(){super.onCreate();serviceAlive=true;Notification n=notification();if(Build.VERSION.SDK_INT>=34)startForeground(1,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE);else startForeground(1,n);wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"ConfigMonitor:checks");wake.setReferenceCounted(false);wake.acquire(10*60*1000L);cm=(ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE);callback=new ConnectivityManager.NetworkCallback(){public void onAvailable(Network n){networkChanged();}public void onLost(Network n){networkChanged();}};cm.registerDefaultNetworkCallback(callback);App.db.breakContinuity();if(App.prefs.getBoolean("running",false))App.db.rearmSession();Alerts.restore();clock.scheduleWithFixedDelay(()->{try{tick();}catch(Exception ignored){}},1,1,TimeUnit.SECONDS);}
 void networkChanged(){if(destroyed)return;try{clock.execute(()->{epoch++;due.clear();nextRound=0;});}catch(RejectedExecutionException ignored){}}
 Notification notification(){PendingIntent open=PendingIntent.getActivity(this,1,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent stop=PendingIntent.getBroadcast(this,2,new Intent(this,Actions.class).setAction("stop"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);return new NotificationCompat.Builder(this,"monitor").setSmallIcon(com.configmonitor.app.R.drawable.ic_notification).setContentTitle("Config Monitor").setContentText(App.t("پایش کانفیگ‌ها • بدون VPN گوشی","Monitoring configurations • no device VPN")).setOngoing(true).setSilent(true).setContentIntent(open).addAction(0,App.t("توقف","Stop"),stop).build();}
 @Override public int onStartCommand(Intent i,int f,int id){String a=i==null?"resume":i.getAction();if("start".equals(a)){App.prefs.edit().putBoolean("running",true).apply();clock.execute(this::restartAlarmSession);}else if("reopen".equals(a)){if(App.prefs.getBoolean("running",false))clock.execute(this::restartAlarmSession);}else if("reschedule".equals(a)){clock.execute(()->{epoch++;due.clear();nextRound=0;tick();});}else if("test".equals(a)){long node=i.getLongExtra("id",0);clock.execute(()->{if(node==0){due.clear();nextRound=0;tick();}else {JSONObject m=App.db.get(node);if(m!=null&&m.optBoolean("enabled"))launch(m);}});}else if("alarm_test".equals(a)){Alerts.raise(-1);}else if("stop".equals(a)){App.prefs.edit().putBoolean("running",false).apply();Alerts.stop();stopSelf();}App.update();return App.prefs.getBoolean("running",false)?START_STICKY:START_NOT_STICKY;}
 void restartAlarmSession(){if(destroyed||!App.prefs.getBoolean("running",false))return;epoch++;App.db.rearmSession();due.clear();nextRound=0;tick();}
 boolean connected(){Network n=cm.getActiveNetwork();NetworkCapabilities caps=n==null?null:cm.getNetworkCapabilities(n);return caps!=null&&caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET);}
 void tick(){Platform.sync();try{tickWork();}finally{publishSchedule();Alerts.reconcile();}}
 void publishSchedule(){if(destroyed)return;JSONArray nodes=App.db.all();int enabled=0;for(int i=0;i<nodes.length();i++)if(nodes.optJSONObject(i).optBoolean("enabled",true))enabled++;schedule=new Cadence(App.prefs.getBoolean("running",false),connected(),enabled,busy.size(),0,nextRound,App.interval()*1000L);}

 void tickWork(){if(destroyed)return;AlertSchedule.Window alertWindow=AlertPolicy.window(System.currentTimeMillis());boolean alertWindowOpened=alertWindow.active&&(!lastAlertWindow||alertWindow.since!=lastAlertSince);lastAlertWindow=alertWindow.active;lastAlertSince=alertWindow.since;if(!wake.isHeld())wake.acquire(10*60*1000L);if(!App.prefs.getBoolean("running",false)){if(busy.isEmpty()&&!Alerts.isActive())main.post(this::stopSelf);return;}JSONArray nodes=App.db.all();boolean anyEnabled=false;for(int n=0;n<nodes.length();n++)if(nodes.optJSONObject(n).optBoolean("enabled",true)){anyEnabled=true;break;}if(!anyEnabled){queued=0;return;}if(!connected()){queued=0;if(!offline){offline=true;epoch++;App.db.unknown();Alerts.raise(0);App.update();}else if(alertWindowOpened){Alerts.raise(0);}else if(App.prefs.getLong("networkSnoozeUntil",0)>0&&App.prefs.getLong("networkSnoozeUntil",0)<=System.currentTimeMillis()){App.prefs.edit().remove("networkSnoozeUntil").apply();Alerts.raise(0);}return;}if(offline){offline=false;epoch++;due.clear();nextRound=0;Alerts.dismiss(0);}long now=SystemClock.elapsedRealtime();if(now>=nextRound){nextRound=now+App.interval()*1000L;for(int i=0;i<nodes.length();i++){JSONObject m=nodes.optJSONObject(i);if(m.optBoolean("enabled",true)&&!busy.contains(m.optLong("id")))launch(m);}}queued=0;}

 void launch(JSONObject m){long id=m.optLong("id"),rev=m.optLong("revision"),token=epoch;if(destroyed||!busy.add(id))return;due.put(id,SystemClock.elapsedRealtime()+App.interval()*1000L);active=busy.size();publishSchedule();workers.execute(()->{Engine.Result result;try{result=Engine.test(m);}catch(Throwable e){result=new Engine.Result(false,-1,"engine_error");}final Engine.Result completed=result;try{clock.execute(()->{busy.remove(id);active=busy.size();if(!destroyed&&token!=epoch)nextRound=0;if(!destroyed&&token==epoch&&connected()){boolean alert=App.db.result(id,rev,completed);if(alert)Alerts.raise(id);publishSchedule();App.update();}});}catch(RejectedExecutionException ignored){}});}
 @Override public void onDestroy(){serviceAlive=false;destroyed=true;epoch++;App.db.breakContinuity();try{cm.unregisterNetworkCallback(callback);}catch(Exception ignored){}clock.shutdownNow();workers.shutdownNow();Engine.stopAll();if(wake!=null&&wake.isHeld())wake.release();active=0;queued=0;schedule=new Cadence(false,true,0,0,0,0,App.interval()*1000L);super.onDestroy();App.update();}
 @Override public IBinder onBind(Intent i){return null;}
}
